import * as React from "react";
import { motion } from "framer-motion";
import PlusIcon from "./plusIcon";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import { IndustryItem } from "../interfaces";
import data from "../data/data.json";

type SectionKey = "intro" | "applications" | "keyBenefits" | "products";

const SECTIONS: { key: SectionKey; label: string }[] = [
  { key: "intro", label: "About" },
  { key: "applications", label: "Applications" },
  { key: "keyBenefits", label: "Key Benefits" },
  { key: "products", label: "Products" },
];

const IndustryGrid: React.FC = () => {
  const { t } = useTranslation();
  const sections = t("industry.sections", {
    returnObjects: true,
  }) as IndustryItem[];

  const videoRefs = React.useRef<{ [key: string]: HTMLVideoElement | null }>({});
  const [playing, setPlaying] = React.useState<{ [key: string]: boolean }>({});
  const [openSections, setOpenSections] = React.useState<Record<string | number, SectionKey>>({});

  const getOpenSection = (id: string | number): SectionKey => openSections[id] ?? "intro";

  const handleSection = (id: string | number, key: SectionKey) =>
    setOpenSections(prev => ({ ...prev, [id]: key }));

  const handleVideoToggle = (videoKey: string) => {
    const video = videoRefs.current[videoKey];
    if (!video) return;

    if (video.paused || video.ended) {
      video.play();
      setPlaying((prev) => ({ ...prev, [videoKey]: true }));
    } else {
      video.pause();
      video.currentTime = 0;
      setPlaying((prev) => ({ ...prev, [videoKey]: false }));
    }
  };

  return (
    <>
      {sections.map((section: any, index: number) => {
        const isEven = index % 2 === 0;
        const imageData = images[section.image] || {};
        const videoData = images[section.video] || {};
        const isLast = index === sections.length - 1;
        const videoKey = section.video;
        const sectionId = section.id ?? index;
        const openSection = getOpenSection(sectionId);

        return (
          <section
            key={section.name || index}
            id={data.submenuIndustry[index]}
            className={`space-y-32 py-12 pt-28 -mb-16 ${
              !isLast ? "border-b border-Tofu/20" : ""
            }`}
          >
            <div
              className={`flex flex-col sm:flex-row ${
                isEven ? "" : "sm:flex-row-reverse"
              } gap-12 sm:gap-24`}
            >
              {/* Video or Image */}
              <div className="w-[calc(100%+40px)] sm:w-3/4 -ml-[20px] sm:-ml-0 relative">
                {section.video ? (
                  <div
                    className="relative group"
                    onMouseEnter={() =>
                      setPlaying((prev) => ({ ...prev, [`${videoKey}-hover`]: true }))
                    }
                    onMouseLeave={() => {
                      setPlaying((prev) => ({ ...prev, [`${videoKey}-hover`]: false }));
                      if (playing[videoKey]) {
                        setTimeout(() => {
                          setPlaying((prev) => ({ ...prev, [`${videoKey}-hover`]: false }));
                        }, 1000);
                      }
                    }}
                  >
                    <video
                      ref={(el) => { videoRefs.current[videoKey] = el; }}
                      poster={imageData.src}
                      className="w-full h-auto"
                      preload="metadata"
                    >
                      <source src={videoData.src} type="video/mp4" />
                      <track kind="captions" srcLang="en" label="English" default />
                      Tu navegador no soporta video.
                    </video>
                    <button
                      onClick={() => handleVideoToggle(videoKey)}
                      aria-label={playing[videoKey] ? "Pause video" : "Play video"}
                      className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-black/60 text-white p-4 rounded-full z-10 hover:bg-black/80 transition ${
                        !playing[videoKey] || playing[`${videoKey}-hover`]
                          ? "opacity-100"
                          : "opacity-0 pointer-events-none"
                      }`}
                    >
                      {playing[videoKey] ? (
                        <svg xmlns="http://www.w3.org/2000/svg" className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                          <path d="M6 4h4v16H6zm8 0h4v16h-4z" />
                        </svg>
                      ) : (
                        <svg xmlns="http://www.w3.org/2000/svg" className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                          <path d="M8 5v14l11-7z" />
                        </svg>
                      )}
                    </button>
                  </div>
                ) : (
                  <img
                    src={imageData.src}
                    alt={imageData.alt || section.name}
                    className="w-full h-auto"
                  />
                )}
              </div>

              {/* Content */}
              <div className="w-full sm:w-1/4 text-Tofu">
                <h2 className="head-3 uppercase mb-6">{section.name}</h2>

                {section.documentPDF && (
                  <a
                    href={images[section.documentPDF]?.src}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex body-3 underline mr-4 mb-4"
                  >
                    <img src="/pdf.svg" alt="" className="mr-4" /> View PDF
                  </a>
                )}

                {/* Accordion sections */}
                <div>
                  {SECTIONS.map(({ key, label }) => {
                    const items: { item?: string; subtitle?: string; paragraph?: string; link?: string }[] = section.info?.[key] || [];
                    if (items.length === 0) return null;
                    const isActive = openSection === key;
                    const isIntroActive = key === "intro" && isActive;

                    return (
                      <div key={key} className="border-b border-Tofu/40 last:border-b-0">
                        {/* Header hidden for "intro" while it's the active section */}
                        {!isIntroActive && (
                          <button
                            onClick={() => handleSection(sectionId, key)}
                            aria-expanded={isActive}
                            className="w-full flex justify-between items-center py-4 text-left group"
                          >
                            <span className="head-7 text-Tofu">{label}</span>
                            <PlusIcon isOpen={isActive} className="text-Tofu ml-4 group-hover:opacity-60 transition-opacity" />
                          </button>
                        )}

                        <motion.div
                          initial={false}
                          animate={isActive ? { height: "auto", opacity: 1 } : { height: 0, opacity: 0 }}
                          transition={{ duration: 0.35, ease: [0.25, 0.46, 0.45, 0.94] }}
                          style={{ pointerEvents: isActive ? "auto" : "none" }}
                        >
                          <div className={`text-Tofu ${isIntroActive ? "pt-2 pb-6" : "pb-6"} space-y-2`}>
                            {items.map((entry, i) => {
                              const isFirstSubtitle = !items.slice(0, i).some(s => s.subtitle);
                              if (entry.subtitle)
                                return <h3 key={i} className={`head-7 text-Tofu font-[400] ${!isFirstSubtitle ? "mt-4" : ""}`} dangerouslySetInnerHTML={{ __html: entry.subtitle }} />;
                              if (entry.paragraph)
                                return <p key={i} className="body-4" dangerouslySetInnerHTML={{ __html: entry.paragraph }} />;
                              if (entry.item)
                                return <li key={i} className="list-none relative before:content-['•'] before:absolute before:-left-4 before:top-0 body-4" dangerouslySetInnerHTML={{ __html: entry.item }} />;
                              if (entry.link)
                                return <a key={i} href={`/products#${section.image}`} target="_self" rel="noopener noreferrer" className="text-Tofu hover:underline body-4 w-full block" dangerouslySetInnerHTML={{ __html: entry.link }} />;
                              return null;
                            })}
                          </div>
                        </motion.div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </section>
        );
      })}
    </>
  );
};

export default IndustryGrid;
